let stars = [];
let numStars = 250;
let dnaPoints = 65;
let mutationWave = 1.0;
let mutationColor;
let mutationTriggered = false;

class Star {
  constructor() {
    this.reset();
    this.z = random(-600, 200);
  }

  reset() {
    let angle = random(TWO_PI);
    let r = random(120, 680);
    this.x = cos(angle) * r;
    this.y = sin(angle) * r;
    this.z = -600;
    this.speed = random(1.5, 4.5);
    this.size = random(1.5, 4.0);
    this.hue = random(180, 280); 
  }

  update(speedMult) {
    let angle = atan2(this.y, this.x);
    let r = sqrt(this.x*this.x + this.y*this.y);

    let spin = map(noise(r * 0.003, this.z * 0.003, frameCount * 0.005), 0, 1, 0.002, 0.012);
    angle += spin * speedMult;

    this.z += this.speed * speedMult;

    this.x = cos(angle) * r;
    this.y = sin(angle) * r;

    if (this.z > 200) {
      this.reset();
    }
  }

  draw(baseHue) {
    push();
    translate(this.x, this.y, this.z);

    colorMode(HSB, 360, 100, 100, 1.0);
    noStroke();

    let h = (baseHue + this.hue) % 360;
    fill(h, 65, 95, map(this.z, -600, 200, 0.0, 0.75));
    ellipse(0, 0, this.size, this.size);
    pop();
  }
}

function setup() {
  createCanvas(1280, 720, WEBGL);
  colorMode(HSB, 360, 100, 100, 1.0);

  for (let i = 0; i < numStars; i++) {
    stars.push(new Star());
  }

  mutationColor = color(0, 0, 100); 
  background(0);
}

function draw() {
  push();
  resetMatrix();
  noStroke();
  colorMode(RGB, 255, 255, 255, 1.0);
  fill(0, 0, 0, 0.14);
  rect(-width/2, -height/2, width, height);
  pop();

  let beatVal = window.beatEnergy || 0.0;
  let lowVal = window.audioLow || 0.0;
  let midVal = window.audioMid || 0.0;
  let highVal = window.audioHigh || 0.0;

  let baseColor = 220; 
  if (window.currentChordColor) {
    let chordC = color(window.currentChordColor);
    baseColor = hue(chordC);
  }

  let starSpeedMult = 1.0 + midVal * 2.0 + beatVal * 1.5;
  for (let s of stars) {
    s.update(starSpeedMult);
    s.draw(baseColor);
  }

  push();
  rotateY(frameCount * 0.006 + sin(frameCount * 0.003) * 0.22);
  rotateX(QUARTER_PI + cos(frameCount * 0.002) * 0.12);

  if (beatVal > 0.75 && !mutationTriggered) {
    mutationTriggered = true;
    mutationWave = 0.0;
    mutationColor = (baseColor + random(120, 240)) % 360;
  }
  if (beatVal < 0.5) {
    mutationTriggered = false; 
  }

  if (mutationWave < 1.0) {
    mutationWave += 0.035;
    push();
    noFill();
    stroke(mutationColor, 85, 95, (1.0 - mutationWave) * 0.35);
    strokeWeight(4.5 + midVal * 8.0);
    ellipse(0, 0, mutationWave * 950, mutationWave * 950);
    pop();
  }

  let helixSpacing = 85.0 + lowVal * 165.0; 

  for (let i = 0; i < dnaPoints; i++) {
    let t = map(i, 0, dnaPoints, -500, 500);
    let angle = map(i, 0, dnaPoints, 0, TWO_PI * 4.2) + frameCount * 0.015;

    let ax = cos(angle) * helixSpacing;
    let ay = sin(angle) * helixSpacing;
    let az = t;

    let bx = cos(angle + PI) * helixSpacing;
    let by = sin(angle + PI) * helixSpacing;
    let bz = t;

    let waveVibe = sin(frameCount * 0.35 + i * 0.6) * (highVal * 28.0);
    let vibeX = cos(angle + HALF_PI) * waveVibe;
    let vibeY = sin(angle + HALF_PI) * waveVibe;

    let pColor = (baseColor + i * 4.5) % 360;
    if (mutationWave < 0.65) {
      pColor = lerp(pColor, mutationColor, 1.0 - mutationWave);
    }

    stroke(pColor, 95, 100, 0.08 + beatVal * 0.15);
    strokeWeight(3.5 + midVal * 6.5);
    line(ax, ay, az, bx + vibeX, by + vibeY, bz);

    stroke(pColor, 80, 100, 0.65 + beatVal * 0.35);
    strokeWeight(1.0 + midVal * 2.0);
    line(ax, ay, az, bx + vibeX, by + vibeY, bz);

    noStroke();
    let nodeSize = (10 + sin(frameCount * 0.04 + i) * 3) * (1.0 + beatVal * 0.45);

    let nodeSat = 85;
    let nodeBright = 95;
    if (beatVal > 0.72) {
      nodeSat = map(beatVal, 0.72, 1.0, 85, 0); 
      nodeBright = 100;
    }

    push();
    translate(ax, ay, az);
    fill(pColor, nodeSat, nodeBright, 0.85);
    ellipse(0, 0, nodeSize, nodeSize);
    fill(pColor, 95, 100, 0.18); 
    ellipse(0, 0, nodeSize * 2.0, nodeSize * 2.0);
    pop();

    push();
    translate(bx + vibeX, by + vibeY, bz);
    fill(pColor, nodeSat, nodeBright, 0.85);
    ellipse(0, 0, nodeSize, nodeSize);
    fill(pColor, 95, 100, 0.18);
    ellipse(0, 0, nodeSize * 2.0, nodeSize * 2.0);
    pop();
  }

  pop();
}

